class BinarySearchService<T extends Comparable<? super T>> implements SearchAlgorithm<T> {
    @Override
    public int search(T[] sortedValues, T target) {
        if (sortedValues == null) {
            throw new IllegalArgumentException("sortedValues must not be null");
        }
        if (target == null) {
            throw new IllegalArgumentException("target must not be null");
        }

        int low = 0;
        int high = sortedValues.length - 1;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            T midValue = sortedValues[mid];

            if (midValue == null) {
                throw new IllegalArgumentException("sortedValues must not contain null elements");
            }

            int comparison = midValue.compareTo(target);
            if (comparison == 0) {
                return mid;
            }

            if (comparison < 0) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        return -1;
    }
}

class BinarySearch {
    public static void main(String[] args) {
        SearchAlgorithm<Integer> searchAlgorithm = new BinarySearchService<>();
        Integer[] values = { 2, 3, 4, 10, 40 };
        Integer target = 10;

        int result = searchAlgorithm.search(values, target);
        if (result == -1) {
            System.out.println("Element is not present in array");
        } else {
            System.out.println("Element is present at index " + result);
        }
    }
}

interface SearchAlgorithm<T extends Comparable<? super T>> {
    int search(T[] values, T target);
}

